export function pathWeight(edges: readonly NetEdge[], route: readonly string[]): number | null {
  let total = 0;
  for (let i = 0; i + 1 < route.length; i += 1) {
    const edge = edges.find((candidate) => (candidate.from === route[i] && candidate.to === route[i + 1]) || (candidate.to === route[i] && candidate.from === route[i + 1]));
    if (!edge) return null;
    total += edge.weight ?? 0;
  }
  return total;
}

/** Every shortest simple route from the start to the goal, in a fixed order, with its total. */
export function shortestPaths(route: PathPayload): { distance: number; paths: string[][] } {
  let best = Infinity;
  let paths: string[][] = [];
  const seen = new Set<string>([route.start]);
  const trail = [route.start];
  const visit = (here: string, total: number): void => {
    if (total > best) return;
    if (here === route.goal) {
      if (total < best) { best = total; paths = []; }
      paths.push([...trail]);
      return;
    }
    for (const edge of route.edges) {
      const next = edge.from === here ? edge.to : edge.to === here ? edge.from : null;
      if (next === null || seen.has(next)) continue;
      seen.add(next); trail.push(next);
      visit(next, total + (edge.weight ?? 0));
      seen.delete(next); trail.pop();
    }
  };
  visit(route.start, 0);
  return { distance: best, paths: paths.sort((a, b) => a.join('|').localeCompare(b.join('|'))) };
}

export function isShortestRoute(route: PathPayload, order: readonly string[]): boolean {
  if (order.length < 2 || order[0] !== route.start || order[order.length - 1] !== route.goal || new Set(order).size !== order.length) return false;
  const total = pathWeight(route.edges, order);
  return total !== null && total === shortestPaths(route).distance;
}

export interface DijkstraStep {
  /** The node settled at this step; the first step settles the start. */
  settled: string;
  /** Best known distance to each node after relaxing from the settled node; null while unreached. */
  distance: Record<string, number | null>;
  /** The node each distance comes through. */
  via: Record<string, string | null>;
  /** Nodes settled so far, in order. */
  done: string[];
}

/** Dijkstra's algorithm one settled node at a time, ending when the goal is settled or nothing more is reachable. */
export function dijkstraSteps(route: PathPayload): DijkstraStep[] {
  const distance: Record<string, number | null> = Object.fromEntries(route.nodes.map((node) => [node.id, null]));
  const via: Record<string, string | null> = Object.fromEntries(route.nodes.map((node) => [node.id, null]));
  distance[route.start] = 0;
  const done: string[] = [];
  const steps: DijkstraStep[] = [];
  for (;;) {
    let pick: string | null = null;
    for (const node of route.nodes) {
      const known = distance[node.id];
      if (known === null || known === undefined || done.includes(node.id)) continue;
      if (pick === null || known < distance[pick]!) pick = node.id;
    }
    if (pick === null) break;
    done.push(pick);
    for (const edge of route.edges) {
      const next = edge.from === pick ? edge.to : edge.to === pick ? edge.from : null;
      if (next === null || done.includes(next)) continue;
      const total = distance[pick]! + (edge.weight ?? 0);
      if (distance[next] === null || total < distance[next]!) { distance[next] = total; via[next] = pick; }
    }
    steps.push({ settled: pick, distance: { ...distance }, via: { ...via }, done: [...done] });
    if (pick === route.goal) break;
  }
  return steps;
}

/* ── choice tree ── */

export function treeProblem(payload: unknown): string | null {
  if (!exactKeys(payload, ['items', 'pick', 'mode'], ['first'])) return 'A choice tree payload holds items, a pick count and a mode';
  const items = payload.items;
  if (!Array.isArray(items) || items.length < TREE_ITEM_MIN || items.length > TREE_ITEM_MAX || !items.every((id) => typeof id === 'string' && ITEM_ID.test(id)) || new Set(items).size !== items.length) {
    return `A choice tree has ${TREE_ITEM_MIN} to ${TREE_ITEM_MAX} different items`;
  }
  if (!isWhole(payload.pick, 2, 3) || payload.pick > items.length) return 'The pick count is 2 or 3 and never above the item count';
  if (payload.mode !== 'order' && payload.mode !== 'group') return 'The tree mode is order or group';
  if (treeLeaves(payload as unknown as TreePayload).length > TREE_LEAF_MAX) return `A tree has at most ${TREE_LEAF_MAX} outcomes`;
  if (payload.mode === 'order') {
    if (typeof payload.first !== 'string' || !items.includes(payload.first)) return 'The order mode names the item that comes first';
    if (treeLeaves(payload as unknown as TreePayload).filter((leaf) => leaf[0] === payload.first).length < 2) return 'At least two outcomes start with the named item';
  } else {
    if (payload.first !== undefined) return 'The group mode names no first item';
    if (items.length === payload.pick) return 'A group of every item has one team only';
  }
  return null;
}

/** Every ordered pick of `pick` different items, in item order: the leaves of the tree. */
export function treeLeaves(tree: TreePayload): string[][] {
  const leaves: string[][] = [];
  const build = (prefix: string[]): void => {
    if (prefix.length === tree.pick) { leaves.push(prefix); return; }
    for (const item of tree.items) if (!prefix.includes(item)) build([...prefix, item]);
  };
  build([]);
  return leaves;
}

export const leafId = (leaf: readonly string[]): string => leaf.join('.');
export const teamOf = (tree: TreePayload, leaf: readonly string[]): string => [...leaf].sort((a, b) => tree.items.indexOf(a) - tree.items.indexOf(b)).join('.');
export const teamIds = (tree: TreePayload): string[] => [...new Set(treeLeaves(tree).map((leaf) => teamOf(tree, leaf)))];

/** Whether the kept outcomes are what the task asks: every outcome that starts with the named item, or exactly one outcome per team. */
export function treeMet(tree: TreePayload, kept: readonly string[]): boolean {
  const leaves = treeLeaves(tree);
  const known = new Map(leaves.map((leaf) => [leafId(leaf), leaf]));
  if (kept.some((id) => !known.has(id)) || new Set(kept).size !== kept.length) return false;
  if (tree.mode === 'order') return sameSet(kept as string[], leaves.filter((leaf) => leaf[0] === tree.first).map(leafId));
  const teams = kept.map((id) => teamOf(tree, known.get(id)!));
  return new Set(teams).size === teams.length && teams.length === teamIds(tree).length;
}

/** One example key: the first outcome of each team, or every outcome that starts with the named item. */
export function treeKey(tree: TreePayload): string[] {
  const leaves = treeLeaves(tree);
  if (tree.mode === 'order') return leaves.filter((leaf) => leaf[0] === tree.first).map(leafId);
  const seen = new Set<string>();
  const keep: string[] = [];
  for (const leaf of leaves) { const team = teamOf(tree, leaf); if (!seen.has(team)) { seen.add(team); keep.push(leafId(leaf)); } }
  return keep;
}

/* ── Pascal's triangle ── */

export function pascalProblem(payload: unknown): string | null {
  if (!exactKeys(payload, ['rows', 'multiple'])) return 'A Pascal payload holds a row count and a multiple';
  if (!isWhole(payload.rows, PASCAL_ROWS_MIN, PASCAL_ROWS_MAX) || !isWhole(payload.multiple, PASCAL_MULTIPLE_MIN, PASCAL_MULTIPLE_MAX)) {
    return `The triangle has ${PASCAL_ROWS_MIN} to ${PASCAL_ROWS_MAX} rows and the multiple is ${PASCAL_MULTIPLE_MIN} to ${PASCAL_MULTIPLE_MAX}`;
  }
  if (pascalMultiples(payload as unknown as PascalPayload).length === 0) return 'At least one cell is a multiple of the number';
  return null;
}

export const pascalCellId = (row: number, col: number): string => `r${row}c${col}`;
/** One slot per row of the triangle, so no slot outgrows the answer-shape capacity: row 0 holds 1 cell, row 9 holds 10. */
export const pascalSlotId = (row: number): string => `row-${row}`;
export const pascalSlots = (rows: number): string[] => Array.from({ length: rows }, (_, row) => pascalSlotId(row));
export const pascalRowOf = (cell: string): number | null => {
  const match = /^r(\d+)c\d+$/.exec(cell);
  return match ? Number(match[1]) : null;
};

/** Cells grouped into the slot of their own row, the shape of a Pascal answer. */
export function pascalByRow(cells: readonly string[]): SlotMap {
  const out: Record<string, string[]> = {};
  for (const cell of cells) {
    const row = pascalRowOf(cell);
    if (row === null) continue;
    (out[pascalSlotId(row)] ??= []).push(cell);
  }
  return out;
}

/** A cell sits only in the slot of its own row. */
export const pascalAccepts = (cell: string, slot: string): boolean => {
  const row = pascalRowOf(cell);
  return row !== null && pascalSlotId(row) === slot;
};

/** The value of each cell of the triangle, row by row. */
export function pascalValues(rows: number): number[][] {
  const out: number[][] = [];
  for (let row = 0; row < rows; row += 1) {
    out.push(Array.from({ length: row + 1 }, (_, col) => (col === 0 || col === row ? 1 : out[row - 1]![col - 1]! + out[row - 1]![col]!)));
  }
  return out;
}

export const pascalCells = (rows: number): string[] => pascalValues(rows).flatMap((line, row) => line.map((_, col) => pascalCellId(row, col)));

export function pascalMultiples(pascal: PascalPayload): string[] {
  return pascalValues(pascal.rows).flatMap((line, row) => line.flatMap((value, col) => (value % pascal.multiple === 0 ? [pascalCellId(row, col)] : [])));
}

/* ── the piece ── */

const asGraph = (payload: unknown): GraphPayload | null => (graphProblem(payload) === null ? (payload as GraphPayload) : null);
const asPath = (payload: unknown): PathPayload | null => (pathProblem(payload) === null ? (payload as PathPayload) : null);
const asTree = (payload: unknown): TreePayload | null => (treeProblem(payload) === null ? (payload as TreePayload) : null);
const asPascal = (payload: unknown): PascalPayload | null => (pascalProblem(payload) === null ? (payload as PascalPayload) : null);

/** Returns the first rule the payload breaks for this visual, or null. Total on any input. */
export function networkProblem(visual: unknown, payload: unknown): string | null {
  switch (visual) {
    case 'graph': return graphProblem(payload);
    case 'shortest-path': return pathProblem(payload);
    case 'choice-tree': return treeProblem(payload);
    case 'pascal': return pascalProblem(payload);
    default: return 'This kind has no such visual';
  }
}

export function networkFrame(visual: unknown, payload: unknown): Frame | null {
  if (visual === 'graph') {
    const graph = asGraph(payload);
    if (!graph) return null;
    return graph.task === 'odd'
      ? { pieceIds: graph.nodes.map((node) => node.id), slotIds: [ODD_SLOT], capacities: { [ODD_SLOT]: graph.nodes.length } }
      : { pieceIds: graph.edges.map((edge) => edge.id), slotIds: [WALK_SLOT], capacities: { [WALK_SLOT]: graph.edges.length } };
  }
  if (visual === 'shortest-path') {
    const route = asPath(payload);
    return route ? { pieceIds: route.nodes.map((node) => node.id), slotIds: [ROUTE_SLOT], capacities: { [ROUTE_SLOT]: route.nodes.length } } : null;
  }
  if (visual === 'choice-tree') {
    const tree = asTree(payload);
    if (!tree) return null;
    const leaves = treeLeaves(tree).map(leafId);
    return { pieceIds: leaves, slotIds: [KEEP_SLOT], capacities: { [KEEP_SLOT]: leaves.length } };
  }
  if (visual === 'pascal') {
    const pascal = asPascal(payload);
    if (!pascal) return null;
    const slots = pascalSlots(pascal.rows);
    return { pieceIds: pascalCells(pascal.rows), slotIds: slots, capacities: Object.fromEntries(slots.map((slot, row) => [slot, row + 1])) };
  }
  return null;
}

/** A walk and a route are read in order; a set of nodes, outcomes or cells is not. */
export function networkOrdered(visual: unknown, payload: unknown): boolean {
  return visual === 'shortest-path' || (visual === 'graph' && asGraph(payload)?.task === 'trail');
}

/** The ids the labels must name: nodes (and the bridges of a walk), or the items of a tree; a triangle has none. */
export function networkLabelIds(visual: unknown, payload: unknown): string[] | null {
  if (visual === 'graph') { const graph = asGraph(payload); return graph ? [...graph.nodes.map((node) => node.id), ...(graph.task === 'trail' ? graph.edges.map((edge) => edge.id) : [])] : null; }
  if (visual === 'shortest-path') return asPath(payload)?.nodes.map((node) => node.id) ?? null;
  if (visual === 'choice-tree') return asTree(payload)?.items ?? null;
  if (visual === 'pascal') return asPascal(payload) ? [] : null;
  return null;
}

export function networkLabelsProblem(visual: unknown, payload: unknown, labels: unknown): string | null {
  const ids = networkLabelIds(visual, payload);
  if (ids === null) return 'The payload is malformed, so no label can be checked';
  if (ids.length === 0) return labels === undefined ? null : 'A triangle takes no labels';
  return isRecord(labels) && sameKeys(labels, ids) ? null : 'Labels name every node, bridge or item, and nothing else';
}

/** Whether a placement is what the task asks, by rule; the key lists examples only. */
export function networkMet(visual: unknown, payload: unknown, slots: SlotMap): boolean {
  const frame = networkFrame(visual, payload);
  if (frame === null || Object.keys(slots).some((key) => !frame.slotIds.includes(key))) return false;
  if (visual === 'pascal') {
    const colored = Object.values(slots).flat();
    return Object.entries(slots).every(([slot, cells]) => cells.every((cell) => pascalAccepts(cell, slot))) && sameSet(colored, pascalMultiples(asPascal(payload)!));
  }
  const placed = slots[frame.slotIds[0]!] ?? [];
  if (visual === 'graph') {
    const graph = asGraph(payload)!;
    return graph.task === 'odd' ? sameSet(placed, oddNodes(graph)) : isTrail(graph.edges, placed, true);
  }
  if (visual === 'shortest-path') return isShortestRoute(asPath(payload)!, placed);
  if (visual === 'choice-tree') return treeMet(asTree(payload)!, placed);
  return sameSet(placed, pascalMultiples(asPascal(payload)!));
}

/** A key solution must itself meet the rule, so a wrong key never grades anyone. */
export function networkKeyProblem(visual: unknown, payload: unknown, solutions: readonly SlotMap[]): string | null {
  if (networkProblem(visual, payload) !== null) return 'The payload is malformed';
  if (solutions.length === 0 || solutions.length > KEY_MAX) return `A key lists 1 to ${KEY_MAX} solutions`;
  return solutions.every((solution) => networkMet(visual, payload, solution)) ? null : 'Every solution meets the rule of the task';
}

/** The first key example the model derives, for authors and fixtures. */
export function networkExamples(visual: unknown, payload: unknown): SlotMap[] {
  const slot = networkFrame(visual, payload)?.slotIds[0];
  if (slot === undefined) return [];
  if (visual === 'graph') {
    const graph = asGraph(payload)!;
    return graph.task === 'odd' ? [{ [slot]: oddNodes(graph) }] : eulerTrails(graph).map((trail) => ({ [slot]: trail }));
  }
  if (visual === 'shortest-path') return shortestPaths(asPath(payload)!).paths.map((route) => ({ [slot]: route }));
  if (visual === 'choice-tree') return [{ [slot]: treeKey(asTree(payload)!) }];
  return [pascalByRow(pascalMultiples(asPascal(payload)!))];
}
